-- Fee dues (docs/designs/fee-dues): one immutable, gross-only due per registration x fee type x instalment,
-- copied from the registration's published fee plan and proven against it here. Head generated by prisma migrate diff.

-- CreateTable
CREATE TABLE "app"."fee_due" (
    "id" BIGSERIAL NOT NULL,
    "registration_id" UUID NOT NULL,
    "centre_id" INTEGER NOT NULL,
    "plan_id" INTEGER NOT NULL,
    "fee_type_id" INTEGER NOT NULL,
    "caption_id" INTEGER NOT NULL,
    "due_on" DATE NOT NULL,
    "gross" DECIMAL(14,2) NOT NULL,
    "currency" CHAR(3) NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by" UUID NOT NULL,

    CONSTRAINT "fee_due_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "fee_due_registration_id_fee_type_id_caption_id_key" ON "app"."fee_due"("registration_id", "fee_type_id", "caption_id");

-- CreateIndex
CREATE UNIQUE INDEX "registration_id_centre_id_key" ON "app"."registration"("id", "centre_id");

-- AddForeignKey
ALTER TABLE "app"."fee_due" ADD CONSTRAINT "fee_due_registration_id_centre_id_fkey" FOREIGN KEY ("registration_id", "centre_id") REFERENCES "app"."registration"("id", "centre_id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."fee_due" ADD CONSTRAINT "fee_due_plan_id_fee_type_id_caption_id_fkey" FOREIGN KEY ("plan_id", "fee_type_id", "caption_id") REFERENCES "app"."fee_plan_line"("plan_id", "fee_type_id", "caption_id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."fee_due" ADD CONSTRAINT "fee_due_created_by_fkey" FOREIGN KEY ("created_by") REFERENCES "app"."app_user"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- ---------- Named checks ----------
alter table app.fee_due add constraint fee_due_gross_check check (gross >= 0);

-- ---------- Guard: rules only, so it binds every role. Nested ifs (plpgsql does not short-circuit AND); every
-- comparison is null-safe and a missing or hidden source row refuses. Each message carries its constraint name. ----------
create function app.fee_due_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare
  r_status text; r_course int; r_year text; r_class int;
  p_status text; p_course int; p_year text; p_centre int; p_class int; p_currency text;
  l_amount numeric; l_due date;
begin
  -- the registration's money lock (lock contract, Z8-3); dues.ts takes the same key first
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || new.registration_id::text));
  new.created_at := now();
  new.created_by := coalesce(app.session_user_id(), new.created_by);

  select r.status::text, co.id, a.academic_year, ce.centre_class_id
    into r_status, r_course, r_year, r_class
    from app.registration r
    join app.admission a on a.id = r.admission_id
    join app.course co on co.code = r.course_code
    join app.centre ce on ce.id = r.centre_id
   where r.id = new.registration_id and r.centre_id = new.centre_id;
  if not found then
    raise exception 'the registration is not found: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
  end if;
  if r_status is distinct from 'ACTIVE' then
    raise exception 'dues are for an active registration: constraint "fee_due_registration_guard"' using errcode = '23514', constraint = 'fee_due_registration_guard';
  end if;

  select p.status, p.course_id, p.academic_year, p.centre_id, p.centre_class_id, p.currency
    into p_status, p_course, p_year, p_centre, p_class, p_currency
    from app.fee_plan p where p.id = new.plan_id;
  if not found or p_status is distinct from 'PUBLISHED' then
    raise exception 'dues come from a published plan: constraint "fee_due_plan_guard"' using errcode = '23514', constraint = 'fee_due_plan_guard';
  end if;

  -- the plan is this registration's: its course and year, at its centre or at its centre's class (C1, D1)
  if p_course is distinct from r_course or p_year is distinct from r_year then
    raise exception 'the plan is for another course or year: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
  end if;
  if p_centre is not null then
    if p_centre is distinct from new.centre_id then
      raise exception 'the plan is for another centre: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
    end if;
  elsif r_class is null or p_class is distinct from r_class then
    raise exception 'the plan is for another centre class: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
  end if;

  -- the copy is exact (R6)
  select l.amount, c.due_on into l_amount, l_due
    from app.fee_plan_line l join app.fee_caption c on c.id = l.caption_id
   where l.plan_id = new.plan_id and l.fee_type_id = new.fee_type_id and l.caption_id = new.caption_id;
  if not found or new.gross is distinct from l_amount or new.due_on is distinct from l_due or new.currency is distinct from p_currency then
    raise exception 'a due copies its plan line: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
  end if;

  -- one plan per registration (C11); safe under the lock above
  if exists (select 1 from app.fee_due d where d.registration_id = new.registration_id and d.plan_id <> new.plan_id) then
    raise exception 'a registration''s dues come from one plan: constraint "fee_due_plan_guard"' using errcode = '23514', constraint = 'fee_due_plan_guard';
  end if;
  return new;
end $$;
create trigger fee_due_guard before insert on app.fee_due for each row execute function app.fee_due_guard();
create trigger fee_due_no_update_delete before update or delete on app.fee_due
  for each row execute function app.ticket_immutable();
create trigger fee_due_no_truncate before truncate on app.fee_due
  for each statement execute function app.ticket_immutable();

-- ---------- RLS: student.view reads, fee.dues creates; update and delete never (T-RLS-002's four commands) ----------
alter table app.fee_due enable row level security;
alter table app.fee_due force row level security;
create policy fee_due_select on app.fee_due for select using (centre_id = any ((select app.scoped_centre_ids('student.view'))::int[]));
create policy fee_due_insert on app.fee_due for insert with check (centre_id = any ((select app.scoped_centre_ids('fee.dues'))::int[]));
create policy fee_due_update on app.fee_due for update using (false);
create policy fee_due_delete on app.fee_due for delete using (false);

-- ---------- Permission; the system administrator holds every permission (0013) ----------
insert into app.permission (key, description, sensitive) values
  ('fee.dues', 'Create a learner''s fee dues from the fee plan', false)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key) select id, 'fee.dues' from app.role where key = 'system_admin'
on conflict do nothing;

-- ---------- Grants: who and when are the guard's ----------
grant select, insert (registration_id, centre_id, plan_id, fee_type_id, caption_id, due_on, gross, currency) on app.fee_due to gems_app;
grant usage on sequence app.fee_due_id_seq to gems_app;
